(()=>{if(!document.querySelector('link[rel="manifest"]')){const e=document.createElement('link');e.rel='manifest';e.href='/app/manifest.json';document.head.appendChild(e)}if(!document.querySelector('meta[name="theme-color"]')){const e=document.createElement('meta');e.name='theme-color';e.content='#05002e';document.head.appendChild(e)}if('serviceWorker'in navigator){navigator.serviceWorker.getRegistration().then(e=>{e||navigator.serviceWorker.register('/app/service-worker.js').catch(()=>{})})}})();
